solution:
import { useState } from 'react';

export function useClamp(initial, min, max) {
  const [value, setValue] = useState(initial);
  return {
    value,
    increment: () => setValue(v => Math.min(v + 1, max)),
    decrement: () => setValue(v => Math.max(v - 1, min)),
  };
}
